INSERT INTO `m_forumtopic` (`id_topik`, `id_unitkerja`, `nama_topik`, `user_id`, `tgl_buat`) VALUES
(1, 'dinkes', 'Tidak bisa buka tabel', 'dinkes', '2019-05-16'),
(2, 'bpom', 'Yth. Sdri Tri nurkhayati\napa ada kendala dalam kegiatan jawa tengah dalam angka ?? trimakasih', 'novi', '2019-05-29'),
(3, 'dinpendidikan', 'bapak amron yang saya hormati,\nberdasarkan pengamatan pada data yang sudah bapak kirim, ada beberapa yang perlu dicermati,\ndiantaranya adalah\n1. terjadinya pertambahan jumlah sekolah, murid, dan guru yang sangat signifikan bila dibandingkan dengan data tahun pendidikan 2016/2017\n2. ada beberapa data yang jika dilihat dari rasio murid-guru, terjadi perubahan nilai yang sangat signifikan. hal ini dimungkinkan terjadi kesalahan entri\n3. data pada periode sebelumnya bisa dilihat di sheet 2017 4.1.3.', 'mira', '2019-06-10'),
(4, 'kopertaisx', 'Bapak Rosikhan yang saya hormati, apakah update data dari perguruan tinggi sudah bisa diinput?\nmohon hubungi kami jika ditemukan kesulitan dalam input data..\n\nterima kasih', 'mira', '2019-06-10'),
(5, 'kopertis6', 'Bapak Donny yang saya hormati, apakah update data dari perguruan tinggi sudah bisa diinput? mohon hubungi kami jika ditemukan kesulitan dalam input data.. terima kasih', 'mira', '2019-06-10'),
(6, 'uin', 'Bapak Agus Sutikno yang saya hormati, apakah update data dari perguruan tinggi sudah bisa diinput? mohon hubungi kami jika ditemukan kesulitan dalam input data.. terima kasih', 'mira', '2019-06-10'),
(7, 'dinsos', 'apakah bisa mengganti format formnya ? MISAL MENGHILANGKAN RINCIANNYA,', 'dinsos', '2019-08-02'),
(8, 'achmadyani', 'test', 'diseminasi', '2020-01-17'),
(9, 'dinkes', 'data tidak tersedia', 'dinkes', '2021-02-03'),
(10, 'kpu', 'kendala pada saat menambahkan tabel untuk pengisian data baru', 'kpujateng', '2023-01-26'),
(11, 'bpn', '[removed]alert&#40;\"1\"&#41;[removed]', 'bpn', '2024-11-30'),
