INSERT INTO `m_list_tabel` (`id`, `judul_ind`, `judul_en`, `id_unitkerja`, `kondef`) VALUES
(1, 'Jumlah Sertifikat Yang Ditebitkan kantor Pertanahan Per Jenis Hak Menurut Kabupaten/Kota di Provinsi Jawa Tengah', 'Number Of Certificate Issued by Land Office Per Type of Rights by Regency/Municipality in Jawa Tengah Province', 'bpn', 'Jumlah Sertipikat yang diterbitkan di Kota Pekalongan :\nHM       :    87.284 \nHGU     :               2\nHGB     :       4.353\nHP        :      3.619\nHW      :          901'),
(3, 'Jumlah Kecamatan Menurut Kabupaten/Kota di Provinsi Jawa Tengah', 'Number of Sub Districts and Villages by Regency/Municipality in Jawa Tengah Province', 'biropem', 'Keputusan Mendagri No.100.1.1-6117 Th 2022 tentang Pemberian dan pemutakhiran Kode, Data Wilayah Administrasi Pemerintahan dan Pulau'),
(4, 'Jumlah Anggota Dewan Perwakilan Rakyat Daerah Provinsi Menurut Partai Politik dan Jenis Kelamin (orang) di Provinsi Jawa Tengah', 'Number of Members of The Regional House of Representatives by Political Parties and Sex in Jawa Tengah Province', 'sekdprd', '-Data yang diisi adalah data per Januari 2023'),
(6, 'Jumlah Pegawai Pemerintah dengan Perjanjian Kerja (PPPK) Menurut Kelompok Umur dan Jenis Kelamin di Pemerintah Provinsi Jawa Tengah', 'Number of State Employees with Employment Agreements by Age Group and Sex in Jawa Tengah Province', 'bkd', '-'),
(7, 'Jumlah Pegawai Negeri Sipil Menurut Jabatan dan Jenis Kelamin di Provinsi Jawa Tengah', 'Number of Government Employee by Occupation and Sex in Jawa Tengah Province', 'bkn', '-'),
(8, 'Banyaknya Pegawai Negeri Sipil Peserta Program PT. Taspen (Persero) Menurut Kabupaten/Kota, Pangkat/Golongan dan Jenis Kelamin di Jawa Tengah', 'Number of Government Employee as Participant of PT Taspen (Persero)1 Program Breakdown by Regency/ Municipality, Group Level, and Sex in Jawa Tengah Province', 'taspen', 'Merupakan Pegawai Negeri Sipil (PNS) Pemerintah Daerah di wilayah Jawa Tengah yang dibagi berdasarkan wilayah administratif Kabupaten/Kota/Provinsi, pangkat/golongan, dan jenis kelamin yang mengikuti program asuransi sosial yang dikelola oleh PT Taspen (Persero)'),
(11, 'Laporan Penerbitan Akta Perkawinan Berdasarkan Domisili Kepemilikan Akta Pencatatan Sipil Menurut  Kabupaten/Kota di Provinsi Jawa Tengah', 'Report of Issuance of Marriage Certificate Based on Domicile Ownership of Civil Registration Certificate by Regency/Municipality in Jawa Tengah Province', 'disdukcapil', '-'),
(12, 'Laporan Penerbitan Akta Perceraian Berdasarkan Domisili Kepemilikan Akta Pencatatan Sipil Menurut  Kabupaten/Kota di Provinsi Jawa Tengah', 'Report of Issuance of Deed of Divorce by Domicile Ownership of Civil Registration Certificate by Regency/ Municipality in Jawa Tengah Province', 'disdukcapil', '-'),
(14, 'Banyaknya Mahasiswa dan Dosen Pada Perguruan Tinggi Agama Islam Swasta di Provinsi Jawa Tengah', 'Number of Pupils and Lecturers of Non Government Islamic Universities in Jawa Tengah Province', 'kopertaisx', '-'),
(15, 'Perolehan Medali Kontingen Jawa Tengah Dalam Pon XX Menurut Cabang Olahraga', 'Number of Medals Achieved by Jawa Tengah Team in PON XX by Branch of Sport', 'koni', '-Perolehan Medali Kontingen Jawa Tengah Dalam PON XIX/Jawa Barat'),
(16, 'Jumlah Satuan Pendidikan, Kepala Sekolah dan Pendidik, serta Peserta Didik Madrasah Ibtidaiyah (MI) di Bawah Kementerian Agama Menurut Kabupaten/Kota di Provinsi Jawa Tengah', 'Number of Schools, Headmasters and Teachers, and Pupils in Madrasah Ibtidaiyah (MI) Under the Ministry of Religious Affairs by Regency/Municipality in Jawa Tengah Province', 'kemenag', '-'),
(17, 'Jumlah Satuan Pendidikan, Kepala Sekolah dan Pendidik, serta Peserta Didik Sekolah Dasar (SD) di Bawah Kementerian Pendidikan Dasar dan Menengah Menurut\r\nKabupaten/Kota di Provinsi Jawa Tengah', 'Number of Schools, Headmasters and Teachers, and Pupils in Elementary Schools Under the Ministry of Primary and Secondary Education, Odd Semester Report Data by Regency/Municipality in Jawa Tengah Province', 'dinpendidikan', 'Jumlah Sekolah, Guru, dan Murid Sekolah Dasar (SD) sumber data kemendikbud dibawah kewenangan Dinas Pendidikan Kabupaten/Kota'),
(18, 'Banyaknya Mahasiswa dan Dosen Pada Perguruan Tinggi Swasta (PTS) Menurut PTS di Jawa Tengah', 'Number of Pupils and Lecturers from Non-Government Universities in Jawa Tengah', 'lldikti', '-'),
(19, 'Proyeksi Beban Pencemaran Udara Menurut Sumber di Jawa Tengah (Ton/Tahun)', 'Air Contamination by Source in Jawa Tengah (Ton/Year)', 'lingkunganhidup', '-'),
(20, 'Proyeksi Beban Pencemaran Udara Menurut Industri di Jawa Tengah (Ton/Tahun)', 'Air Contamination by Industry in Jawa Tengah (Ton/Year)', 'lingkunganhidup', '-'),
(21, 'Jumlah Rumah Sakit Umum, Rumah Sakit Khusus, Puskesmas, Klinik Pratama, dan Posyandu Menurut Kabupaten/Kota di Provinsi Jawa Tengah', 'Number of General Hospital, Specialized Hospital, Public Health Center, Primary Clinic, and Integrated Health Post By Regency/Municipality in Jawa Tengah Province', 'dinkes', '- Rumah Sakit adalah Institusi pelayanan kesehatan yang menyelenggarakan pelayanan kesehatan perorangan secara paripurna yang menyediakan pelayanan \nrawat inap, rawat jalan, dan gawat darurat\n- Rumah sakit umum adalah Rumah sakit yang memberikan pelayanan kesehatan pada semua bidang dan jenis penyakit\n- Rumah sakit khusus adalah Rumah sakit yang memberikan pelayanan utama pada satu bidang atau satu jenis penyakit tertentu berdasarkan disiplin ilmu, golongan umur, organ, jenis penyakit, atau kekhususan lainnya\n- Puskesmas rawat inap adalah Puskesmas yang diberi tambahan sumberdaya untuk menyelenggarakan pelayanan rawat inap, sesuai pertimbangan kebutuhan \npelayanan kesehatan\n- Puskesmas non rawat inap : Puskesmas yang tidak menyelenggarakan pelayanan rawat inap kecuali pertolongan persalinan normal\n- Klinik Pratama : Klinik yang menyelenggarakan pelayanan medik dasar baik umum maupun khusus'),
(22, 'Kasus Penyakit Menurut Kabupaten/Kota dan Jenis\r\nPenyakit di Provinsi Jawa Tengah', 'Number Disease Cases by Regency/Municipality and Type of Disease in Jawa Tengah Province', 'dinkes', '-'),
(23, 'Jumlah Klinik Keluarga Berencana (KKB) dan Pos \nPelayanan  Keluarga Berencana Desa (PPKBD) Menurut \nKabupaten/Kota di Provinsi Jawa Tengah', 'Number of Family Planning Clinics (KKB) and Village Family\nPlanning Service Posts (PPKBD) by Regency/Municipality in\nJawa Tengah Province', 'bkkbn', 'PPKBD adalah wadah \norganisasi di tingkat desa/kelurahan yang diketuai oleh seorang atau beberapa orang \nkader yang secara sukarela berperan aktif melaksanakan/mengelola Program \nKependudukan, Keluarga Berencana dan Pembangunan Keluarga di tingkat \ndesa/kelurahan atau yang setara.'),
(24, 'Jumlah Pasangan Usia Subur dan Peserta KB Aktif \nMenurut Kabupaten/Kota di Provinsi Jawa Tengah', 'Number of Fertile Age Couples and Active Family Planning Kabupaten/Kota Regency/Municipality Participants by Regency/Municipality in Jawa Tengah Province', 'bkkbn', 'Pasangan Usia Subur (PUS) adalah pasangan suami-istri yang terikat dalam \nperkawinan yang sah, yang istrinya berumur antara 15 sampai dengan 49 tahun.\nPeserta KB Aktif adalah Pasangan Usia Subur (PUS) yang saat ini \nmenggunakan salah satu alat kontrasepsi tanpa diselingi kehamilan.'),
(25, 'Peserta KB Baru Menurut Kabupaten/Kota di Provinsi \nJawa Tengah', 'New Family Planning Acceptors by Regency/ Multicipality in \nJawa Tengah Province', 'bkkbn', 'Peserta KB Baru adalah pasangan usia subur yang baru pertama kali \nmenggunakan alat/cara kontrasepsi dan atau pasangan usia subur yang kembali \nmenggunakan metode kontrasepsi setelah melahirkan/keguguran.'),
(26, 'Banyak dan Jenis Sarana Produksi Sediaan Farmasi dan  Makanan yang Diperiksa di Kabupaten/Kota Provinsi di  Jawa Tengah', 'Number and Kinds of Under License Pharmaceutical and Food Manufactures by Regency/Municipality in Jawa Tengah Province', 'bpom', '-'),
(27, 'Banyak dan Jenis Sarana Distribusi Obat Yang Ada Menurut Kabupaten/Kota di Provinsi Jawa Tengah', 'Number and Kinds of Under License Medicine and Food  Kabupaten/Kota Regency/Municipality Distribution by Regency/Municipality in Jawa Tengah Province', 'bpom', '-'),
(28, 'Banyak dan Jenis Sarana Distribusi Sediaan Farmasi dan Makanan Yang Diperiksa Menurut Kabupaten/Kota di Provinsi Jawa Tengah', 'Number and Kinds of Under License Medicine and Food\nDistribution by Regency/Municipality in Jawa Tengah\nProvince', 'bpom', '-'),
(30, 'Jumlah Bayi Lahir, Bayi Berat Badan Lahir Rendah (BBLR), dan Bergizi Kurang Menurut Kabupaten/Kota di Provinsi Jawa Tengah', 'Number of Births, Babies with Low Birth Weights (LBW), and Malnutrition by Regency/Municipality in Jawa Tengah Province', 'dinkes', '-'),
(31, 'Jumlah Ibu Hamil, Melakukan Kunjungan K1, Melakukan Kunjungan K4, Kurang Energi Kronis (KEK), dan Mendapat Tablet Zat Besi (Fe) di Provinsi Jawa Tengah', 'Number of Pregnant Women, Conducting K1 Visits, Conducting K4 Visits, Chronic Energy Lack, and Getting Iron Tablets (Fe) in Jawa Tengah Province', 'dinkes', '-'),
(32, 'Jumlah Penduduk  Menurut Kabupaten/Kota dan Agama \nyang Dianut di Provinsi Jawa Tengah', 'Population by Regency/Municipality and Religion in Jawa \nTengah Province', 'kemenag', '-'),
(33, 'Jumlah Tempat Peribadatan Menurut Kabupaten/Kota di \nProvinsi Jawa Tengah', 'Number of Places of Worship by Regency/Municipality and \nReligion in Jawa Tengah Province', 'kemenag', '-'),
(34, 'Jumlah Tindak Pidana, Risiko Penduduk Terjadi Tindak Pidana per 100.000 Penduduk, Persentase Penyelesaian Tindak Pidana, dan  Selang Waktu Terjadinya Tindak Pidana Menurut Kepolisian Daerah', 'Number of Crime, Crime Rate per 100,000 Population, Percentage of Crime Clearance, and Time Interval of Crime Occurance by Regional Police Office by Regency/Municipality in Jawa Tengah Province', 'polda', '-Pengertian tindak pidana dalam Kitab Undang-undang Hukum Pidana (KUHP) dikenal dengan istilah stratbaar feit dan dalam kepustakaan tentang hukum pidana sering mempergunakan istilah delik, sedangkan pembuat undang-undang merumuskan suatu undang-undang mempergunakan istilah peristiwa pidana atau perb'),
(35, 'Banyaknya Kejahatan di Provinsi Jawa Tengah Menurut Polres, Polresta, dan Polrestabes', 'Number of Crime in Jawa Tengah Province by Region of  Wilayah Region Police Departement', 'polda', '-pengertian kejahatan menurut pendapat para ahli, antara lain :\nMenurut Soesilo (Husein, 2003) ada dua pengertian kejahatan, yaitu pengertian kejahatan secara juridis dan pengertian kejahatan secara sosiologis. Ditinjau dari segi juridis, kejahatan adalah suatu perbuatan tingkah laku yang bertentang'),
(37, 'Banyaknya Kecelakaan Lalu Lintas, Korban dan Nilai Kerugiannya di Wilayah Polda Jawa Tengah', 'Number of Traffic Accidents, Victims and Loss in Jawa  Wilayah Region Tengah Province by Region of Police Depertment', 'polda', '-Kecelakaan lalu-lintas adalah kejadian di mana sebuah kendaraan bermotor tabrakan dengan benda lain dan menyebabkan kerusakan. Kadang kecelakaan ini dapat mengakibatkan luka-luka atau kematian manusia atau binatang. '),
(38, 'Banyaknya Pos Keamanan Lingkungan (Poskamling) di Wilayah Polda  Jawa Tengah', 'Number of Environmental Security Post in Region of Police of Jawa Tengah', 'polda', '-Kepanjangan dari singkatan Pos Kamling, atau arti dari singkatan Pos Kamling adalah pos keamanan keliling, dimana ianya adalah merupakan pos jaga bagi para linmas atau hansip yang biasa berjaga dimalam hari demi untuk keamanan blok , kampung maupun desa dimana mereka bertempat atau bertugas. '),
(40, 'Banyaknya Perkara Pidana Khusus Anak yang Masuk, Diputus, dan Sisa di Pengadilan Tinggi Provinsi Jawa Tengah', 'Number of Child Cases which Reported, Finished, and Rest in High Court of Jawa Tengah Province', 'pengtinggi', '- Perkara Masuk : 35\n- Perkara Putus : 35\n- Sisa Perkara : 0'),
(41, 'Banyaknya Perkara Pidana Korupsi yang Masuk, Diputus dan Sisa di Pengadilan Tinggi Provinsi Jawa Tengah', 'Number of Corruption Cases which Reported, Finished, and Rest in High Court of Jawa Tengah Province', 'pengtinggi', '- Perkara Masuk : 36\n- Perkara Putus : 34\n- Sisa Perkara : 2'),
(42, 'Banyaknya Perkara Perdata yang Masuk, Diputus, dan Sisa di Pengadilan Tinggi Provinsi Jawa Tengah', 'Number of Civil Cases which Reported, Finished, and Rest in High Court of Jawa Tengah Province', 'pengtinggi', '- Perkara Masuk : 631\n- Perkara Putus : 633\n- Sisa Perkara : 8'),
(43, 'Banyaknya Terdakwa/Tertuduh yang Diselesaikan Pengadilan Negeri/Tinggi Menurut Unit Pelaksana Teknis dan Sikap Terhadap Keputusan Pengadilan Negeri di Jawa Tengah', 'Number of Accused which Finish of Government Court by Government Court and Attitude to Decision in Jawa Tengah', 'pengtinggi', '-'),
(46, 'Rekapitulasi Jumlah Narapidana dan Anak Pidana Berdasarkan Tindak Pidana di Provinsi Jawa Tengah', 'Recapitulation of Number of Prisoners and Criminal Children by Criminal Act in Jawa Tengah Province', 'kemenkumham', '-'),
(48, 'Banyaknya Lembaga Kesejahteraan Sosial Penyandang Disablitas/ Panti Khusus dan Jumlah Penghuni Menurut Kabupaten/Kota di Provinsi Jawa Tengah', 'Number of Special Asylum and Number of Inhabitants by Regency/Municipality in Jawa Tengah Province', 'dinsos', '-'),
(49, 'Banyaknya Karang Taruna Menurut Kabupaten/Kota di Jawa Provinsi Tengah', 'Number of \"Karang Taruna\" by Regency/Municipality in Jawa Tengah Province', 'dinsos', '-'),
(50, 'Banyaknya Peserta BPJS Kesehatan Menurut Kabupaten/\nKota di Provinsi Jawa Tengah', 'Number of Health Insurance Participant by Regency/ Kabupaten/Kota Regency/Municipality Multicipality in Jawa Tengah Province', 'bpjs', '-'),
(51, 'Banyaknya Perkara yang Diputus Pengadilan Agama di \nWilayah Pengadilan Tinggi Agama (PTA) Provinsi Jawa \nTengah Menurut Jenis Perkara', 'Number of Cases Decided By Religion High Court of Jawa\nTengah Province by Kind of Cases', 'pengadilanagama', '-'),
(52, 'Banyaknya Hakim, Panitera/Panitera Pengganti dan Juru \nSita Menurut Pengadilan Negeri di Provinsi Jawa Tengah \nMenurut Jenis Perkara', 'Number of Cases Decided By Religion High Court of Jawa\nTengah Province by Kind of Cases', 'pengtinggi', 'Jumlah Data Pengadilan Negeri se Jawa Tengah\nHakim : 316 orang\nPanitera/Panitera Pengganti : 341 orang\nJurusita : 201 orang\n'),
(53, 'Luas dan Produksi Tanaman Perkebunan PTPN IX Menurut Jenis Tanaman di Provinsi Jawa Tengah (ha)', 'Area and Production of Government Large Estate by Kind of Crops in Jawa Tengah Province (ha)', 'ptpn_ix', '-'),
(54, 'Luas Areal Tanaman Perkebunan Menurut Kabupaten/ Kota dan Jenis Tanaman di Provinsi Jawa Tengah (hektar)', 'Planted Area of Estate Crops by Regency/Municipality and Type of Crops in Jawa Tengah Province (hectare)', 'pertanian', '-'),
(55, 'Produksi Perkebunan Menurut Kabupaten/Kota dan Jenis Tanaman di Provinsi Jawa Tengah (ton)', 'Production of Estate by Regency/Municipality and Type of Crops in Jawa Tengah Province (ton)', 'pertanian', '-'),
(56, 'Populasi Ternak Menurut Kabupaten/Kota dan Jenis Ternak di Provinsi Jawa Tengah (ekor)', 'Livestock Population by Regency/Municipality and Kind \nof Livestock in Jawa Tengah Province (heads)', 'ternaksehat', '-Kumpulan  atau jumlah ternak  yang hidup pada wilayah dan satu waktu tertentu, kecuali ayam ras pedaging'),
(57, 'Populasi Unggas Menurut Kabupaten/Kota dan Jenis Unggas di Provinsi Jawa Tengah (ekor)', 'Poultry Population by Regency/Municipality and Kind of \nKabupaten/Kota Regency/Municipality Poultry in Jawa Tengah Province (heads)', 'ternaksehat', '-populasi ayam ras pedaging komersial yang hidup dan pernah hidup di dalam usaha budidaya selama setahun'),
(58, 'Produksi Daging Ternak Menurut Kabupaten/Kota dan Jenis Ternak di Provinsi Jawa Tengah (kg)', 'Meat Production by Regency/Municipality and Kind of \n Livestock in Jawa Tengah Province (kg)', 'ternaksehat', '-Karkas hasil pemotongan ternak di wilayah tersebut ditambah dengan bagian yang dapat dimakan (edibel portion) selama waktu tertentu'),
(59, 'Produksi Daging Unggas Menurut Kabupaten/Kota dan Jenis Unggas di Provinsi Jawa Tengah (kg)', 'Poultry Meat Production by Regency/Municipality and Kind \nKabupaten/Kota Regency/Municipality of Poultry in Jawa Tengah Province (kg)', 'ternaksehat', '--Karkas hasil pemotongan ternak di wilayah tersebut ditambah dengan bagian yang dapat dimakan (edibel portion) selama waktu tertentu'),
(60, 'Jumlah Rumah Tangga Perikanan Tangkap Menurut Kabupaten/Kota dan Subsektor di Provinsi Jawa Tengah', 'Number of Fish Capture Households by Regency/\nMunicipality and Subsector in Jawa Tengah Province', 'dkp', '- Rumah Tangga Perikanan Tangkap adalah Rumah tangga yang melakukan kegiatan penangkapan ikan/binatang air'),
(61, 'Volume Produksi dan Nilai Produksi Perikanan Tangkap Menurut Kabupaten/Kota dan Jenis Penangkapan di Provinsi Jawa Tengah', 'Production and Production Value of Fish Capture by Regency/Municipality and Type of Captures in Jawa Tengah Province', 'dkp', '- Volume produksi adalah berat basah pada waktu hasil tangkapan di daratkan.  Mencakup semua hasil penangkapan ikan/binatang air lainnya/tanaman air yang ditangkap dari sumber perikanan alami baik yang diusahakan oleh perusahaan perikanan maupun rumah tangga perikanan'),
(63, 'Valume Produksi dan Nilai Produksi Perikanan Tangkap di Laut Menurut Kabupaten/Kota dan Komoditas Utama di Provinsi Jawa Tengah', 'Production and Production Value of Marine Capture Fisheries by Regency/Municipality and Main Commodity in Jawa Tengah Province', 'dkp', '-'),
(65, 'Luas Pembagian Kawasan Hutan Menurut Kabupaten/Kota di Provinsi Jawa Tengah (ha)', 'The Division of Forest Area by Regency/Municipality in Jawa Tengah Province (ha)', 'perhutani', 'kawasan hutan adalah wilayah tertentu yang ditunjuk dan atau telah ditetapkan oleh pemerintah untuk dipertahankan keberadaannya sebagai hutan tetap.'),
(66, 'Produksi Hasil Hutan Menurut Jenis Produksi di Provinsi Jawa Tengah', 'Forest Product Production by Production Type in Jawa Tengah Province', 'perhutani', 'Hasil hutan adalah segala sesuatu yang diperoleh dari dalam hutan untuk dimanfaatkan secara komersil atau untuk kepentingan ekonomi. Hasil hutan dapat berupa hasil hutan kayu dan non kayu (getah, daun dll)\nProduksi hasil hutan yaitu kegiatan memproduksi segala sesuatu yang ada di hutan untuk dimanfaatkan secara komersil'),
(67, 'Luas Penggunaan Lahan dan Luas Kawasan Hutan Menurut Kabupaten/Kota di Provinsi Jawa Tengah (ha)', 'The Area of Region and Forest Area by regency/Municipality in Jawa Tengah Province (ha)', 'lingkunganhidup', '-'),
(68, 'Luas Lahan Kritis di Luar Kawasan Hutan Menurut Kabupaten/Kota di Provinsi Jawa Tengah (ha)', 'Critical Area in Forest Area by Regency/Municipality in Jawa Tengah Province (ha)', 'bpdas', '-'),
(69, 'Jumlah Industri dan Tenaga Kerja Menurut Kabupaten/ Kota di Provinsi Jawa Tengah', 'Number of Industry and Employees by Regency/\n Municipality in Jawa Tengah Province', 'disperindag', '-'),
(70, 'Banyaknya Perusahaan Penyalur dan Banyak Pemakaian \nGas LPG Menurut Kabupaten/Kota di Provinsi Jawa \nTengah', 'Number of Distributor Enterprise and Number of Use Gas by Regency/ Municipality in Jawa Tengah Province', 'pertamina', '-'),
(71, 'Jumlah Pelanggan Listrik Menurut Kabupaten/Kota di Provinsi Jawa Tengah', 'Number of Electricity Customers by Regency/Municipality in Jawa Tengah Province', 'pln', '-'),
